 3	function fib(n: nat):nat
 4	{
 5	    if n < 2 then n else fib(n-2)+fib(n-1)
 6	}
 7	
 8	method fibIter(n:nat) returns (a:nat)
 9	requires n > 0
10	ensures a == fib(n)
11	{
12	    a := 0;
13	    var b,x := 1,0;
14	    while x < n 
15	        invariant 0 <= x <= n
16	        invariant a == fib(x)
17	        invariant b == fib(x+1)
18	        {
19	            a,b := b,a+b;
20	            //why a,b := b,a+b is okay
21	            //but when I write  a := b;      //# Because this  
22	            //                  b := a+b;    //# is not the same  !! 
23	            //is error?                      //# {a = 1 , b = 2 } a := b ; b := a+b { b = 4 }, but 
24	            x := x+1;                        //# {a = 1 , b = 2 }   a, b := b,a+b  { b = 3 }
25	        }
26	    assert a == fib(n);     
27	}
