31	function fact(n:nat):nat
32	{if n==0 then 1 else n*fact(n-1)}
33	
34	method factIter(n:nat) returns (a:nat)
35	requires n >= 0;
36	ensures a == fact(n)
37	{
38	    a := 1;
39	    var i := 1;
40	    while i <= n
41	        invariant 1 <= i <= n+1
42	        invariant a == fact(i-1)
43	    {
44	        a := a * i;
45	        i := i + 1;
46	    }
47	    assert a == fact(n);
48	} 
