51	function gcd(m: nat, n: nat): nat
52	    requires m > 0
53	{
54	    if m == n then m
55	    else if m > n then gcd(m - n, n)
56	    else gcd(m, n - m)
57	}
58	
59	method gcdI(m: int, n: int) returns (g: int)
60	    requires  m > 0 && n > 0 
61	    ensures g == gcd(m, n);
62	    {
63	        var x: int;
64	        g := m;
65	        x := n;
66	        while (g != x)
67	        invariant x > 0;
68	        invariant g > 0;
69	        invariant gcd(g, x) == gcd(m, n);
70	        decreases x+g;
71	        {
72	          if (g > x)
73	          {
74	             g := g - x;
75	          }
76	          else
77	          {
78	             x := x - g;
79	          }
80	        }
81	    }
